namespace Shop;

public enum CustomerType { Regular, Loyal, Student, Partner }

public record OrderLine(string Sku, decimal UnitPrice, int Quantity);

public record Order(CustomerType Customer, IReadOnlyList<OrderLine> Lines);

// A customer type's discount and the receipt line that describes it, kept together
// so a new customer type is added in one place.
public record DiscountRule(string ReceiptLine, Func<decimal, decimal> DiscountOn);

public static class PriceCalculator
{
    public static DiscountRule RuleFor(CustomerType customer) => customer switch
    {
        CustomerType.Regular => new("Regular: no discount", _ => 0m),
        CustomerType.Loyal => new("Loyal: 5% off", subtotal => subtotal * 0.05m),
        CustomerType.Student => new("Student: 10% off, max 30",
            subtotal => Math.Min(subtotal * 0.10m, 30m)),
        CustomerType.Partner => new("Partner: 10% off, 15% off above 1,000",
            subtotal => subtotal * (subtotal > 1000m ? 0.15m : 0.10m)),
        _ => throw new ArgumentOutOfRangeException(nameof(customer), customer, null)
    };

    public static decimal Subtotal(Order order) => order.Lines.Sum(l => l.UnitPrice * l.Quantity);

    public static decimal Total(Order order)
    {
        var subtotal = Subtotal(order);
        return subtotal - RuleFor(order.Customer).DiscountOn(subtotal);
    }

    public static string DiscountReceiptLine(Order order) => RuleFor(order.Customer).ReceiptLine;
}

